INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Rollen und Verantwortlichkeiten ein zentraler Bestandteil der Projektorganisation?', 2, '[{"text": "Ja", "correct": true, "because": "Definieren Zuständigkeiten"}, {"text": "Nein", "correct": false, "because": "Sie sind essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgen Rollen und Verantwortlichkeiten im Projekt?', 3, '[{"text": "Klare Aufgabenverteilung sicherstellen", "correct": true, "because": "Fördert Effizienz"}, {"text": "Kosten direkt senken", "correct": false, "because": "Nebenaspekt"}, {"text": "Zeitplan erstellen", "correct": false, "because": "Planungsaufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Rollen klären Zuständigkeiten. b) Sie werden erst im Abschluss definiert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, früh nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zur Definition von Rollen und Verantwortlichkeiten?', 4, '[{"text": "Aufgabenbeschreibungen", "correct": true, "because": "Definieren Pflichten"}, {"text": "Unklare Zuständigkeiten", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Rollenbeschreibungen", "correct": true, "because": "Klären Positionen"}, {"text": "Entscheidungsbefugnisse", "correct": true, "because": "Legen Kompetenzen fest"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt ohne definierte Rollen erfolgreich sein?', 2, '[{"text": "Nein", "correct": true, "because": "Unklarheit droht"}, {"text": "Ja", "correct": false, "because": "Chaos möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phase definiert Rollen und Verantwortlichkeiten primär?', 3, '[{"text": "Initiierung", "correct": true, "because": "Legt Grundlage"}, {"text": "Durchführung", "correct": false, "because": "Setzt um"}, {"text": "Abschluss", "correct": false, "because": "Beendet Projekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Rollen und Verantwortlichkeiten nur für große Projekte relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte brauchen sie"}, {"text": "Ja", "correct": false, "because": "Breite Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielen Rollen und Verantwortlichkeiten?', 3, '[{"text": "Effiziente Zusammenarbeit fördern", "correct": true, "because": "Vermeiden Doppelarbeit"}, {"text": "Zeitplan direkt erstellen", "correct": false, "because": "Planungsaufgabe"}, {"text": "Kosten direkt überwachen", "correct": false, "because": "Controlling-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Rollen vermeiden Konflikte. b) Sie sind immer unveränderlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, anpassbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne definierte Rollen und Verantwortlichkeiten?', 3, '[{"text": "Unklare Zuständigkeiten", "correct": true, "because": "Führt zu Chaos"}, {"text": "Projekt wird schneller", "correct": false, "because": "Eher Verzögerung"}, {"text": "Kosten sinken", "correct": false, "because": "Ineffizienz möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Projektorganisation ohne Rollen funktionieren?', 2, '[{"text": "Nein", "correct": true, "because": "Struktur fehlt"}, {"text": "Ja", "correct": false, "because": "Unklarheit droht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt eine Rollenzuweisung?', 3, '[{"text": "Projektleiter überwacht Zeitplan", "correct": true, "because": "Klar und spezifisch"}, {"text": "Irgendwer macht etwas", "correct": false, "because": "Zu vage"}, {"text": "Team soll planen", "correct": false, "because": "Keine Rolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Rollen nur für den Projektstart relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Über alle Phasen wichtig"}, {"text": "Ja", "correct": false, "because": "Projektweite Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale haben Rollen und Verantwortlichkeiten?', 4, '[{"text": "Klar definierte Aufgaben", "correct": true, "because": "Fördern Klarheit"}, {"text": "Unklare Kompetenzen", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Entscheidungsbefugnisse", "correct": true, "because": "Legen Rechte fest"}, {"text": "Zuweisung an Personen", "correct": true, "because": "Sichern Zuständigkeiten"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Rollen und Verantwortlichkeiten dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Nachvollziehbarkeit nötig"}, {"text": "Nein", "correct": false, "because": "Dokumentation hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug hilft bei der Definition von Rollen?', 3, '[{"text": "RACI-Matrix", "correct": true, "because": "Klärt Zuständigkeiten"}, {"text": "Keine Struktur", "correct": false, "because": "Fehlt Klarheit"}, {"text": "Zufällige Liste", "correct": false, "because": "Unübersichtlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Rollenzuweisung ohne Projektziele erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Ziele geben Richtung"}, {"text": "Ja", "correct": false, "because": "Unklarheit droht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erschwert die Definition von Rollen?', 3, '[{"text": "Unklare Anforderungen", "correct": true, "because": "Verhindern Zuweisung"}, {"text": "Klarer Zeitplan", "correct": false, "because": "Fördert Struktur"}, {"text": "Gute Kommunikation", "correct": false, "because": "Unterstützt Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Rollen fördern Zusammenarbeit. b) Sie sind nur für technische Projekte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, breit anwendbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen definierter Rollen?', 3, '[{"text": "Vermeidung von Doppelarbeit", "correct": true, "because": "Fördert Effizienz"}, {"text": "Maximale Unklarheit", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Koordination", "correct": false, "because": "Fördert Zusammenarbeit"}]');
